<template>
  <b-container fluid class="py-3">
    <b-row>
      <b-col lg="8" md="7">
        <b-card no-body class="shadow-sm border-0">
          <b-card-header
            class="bg-white d-flex justify-content-between align-items-center py-3"
          >
            <h5 class="mb-0 text-dark">
              <b-icon icon="bank" class="mr-2 text-primary"></b-icon>
              Contas Bancárias
              <b-badge variant="light" pill class="border ml-2">{{
                accounts.length
              }}</b-badge>
            </h5>
            <b-button
              size="sm"
              variant="primary"
              pill
              @click="openAccountModal()"
            >
              <b-icon icon="plus-circle-fill"></b-icon> Nova Conta
            </b-button>
          </b-card-header>

          <b-overlay :show="isLoading" rounded="sm" opacity="0.6">
            <div class="table-responsive">
              <table class="table table-hover mb-0">
                <thead class="thead-light">
                  <tr>
                    <th>Banco / Descrição</th>
                    <th>Número da Conta</th>
                    <th>Titular</th>
                    <th class="text-center">Ações</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-if="accounts.length === 0">
                    <td colspan="4" class="text-center py-5 text-muted">
                      Nenhuma conta bancária configurada.
                    </td>
                  </tr>
                  <tr v-for="account in accounts" :key="account.id">
                    <td class="align-middle font-weight-bold">
                      {{ account.accountDescription }}
                    </td>
                    <td class="align-middle">
                      <code>{{ account.accountNumber }}</code>
                    </td>
                    <td class="align-middle text-muted">
                      {{ account.accountHolder }}
                    </td>
                    <td class="text-center">
                      <b-button-group size="sm">
                        <b-button
                          variant="link"
                          @click="updateAccount(account)"
                          title="Editar"
                        >
                          <b-icon
                            icon="pencil-square"
                            variant="primary"
                          ></b-icon>
                        </b-button>
                        <b-button
                          variant="link"
                          @click="confirmDelete(account)"
                          title="Eliminar"
                        >
                          <b-icon icon="trash" variant="danger"></b-icon>
                        </b-button>
                      </b-button-group>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </b-overlay>
        </b-card>
      </b-col>

      <b-col lg="4" md="5">
        <b-card
          bg-variant="light"
          class="border-0 shadow-sm mb-3 text-center py-3"
        >
          <b-icon
            icon="info-circle"
            font-scale="2"
            class="text-secondary mb-2"
          ></b-icon>
          <h6>Gestão de Tesouraria</h6>
          <p class="small text-muted">
            Configure as contas para as quais os clientes devem efetuar os
            pagamentos das prestações.
          </p>
          <b-button
            size="sm"
            variant="outline-secondary"
            @click="getAllAccounts"
          >
            <b-icon icon="arrow-clockwise"></b-icon> Atualizar Lista
          </b-button>
        </b-card>
      </b-col>
    </b-row>

    <b-modal
      id="modal-account"
      ref="open-account"
      :title="form.id ? 'Atualizar Conta' : 'Registar Nova Conta'"
      centered
      @hidden="resetFields"
    >
      <b-form @submit.prevent="saveAccount">
        <b-form-group
          label="Descrição do Banco (Ex: BCI, Millennium BIM)"
          label-class="font-weight-bold small"
        >
          <b-form-input
            v-model="form.accountDescription"
            placeholder="Nome do banco ou descrição"
            required
          ></b-form-input>
        </b-form-group>

        <b-form-group
          label="Número da Conta / IBAN"
          label-class="font-weight-bold small"
        >
          <b-form-input
            v-model="form.accountNumber"
            type="number"
            placeholder="Digite o número"
            required
          ></b-form-input>
        </b-form-group>

        <b-form-group
          label="Titular da Conta"
          label-class="font-weight-bold small"
        >
          <b-form-input
            v-model="form.accountHolder"
            placeholder="Nome do titular"
            required
          ></b-form-input>
        </b-form-group>
      </b-form>

      <template #modal-footer="{ cancel }">
        <b-button variant="light" size="sm" @click="cancel()"
          >Cancelar</b-button
        >
        <b-button
          variant="success"
          size="sm"
          :disabled="isLoading"
          @click="saveAccount"
        >
          <b-spinner small v-if="isLoading"></b-spinner>
          {{ form.id ? "Salvar Alterações" : "Confirmar Registo" }}
        </b-button>
      </template>
    </b-modal>

    <b-modal
      ref="delete-account"
      title="Confirmar Eliminação"
      centered
      header-bg-variant="danger"
      header-text-variant="white"
    >
      <p>
        Tem a certeza que deseja eliminar a conta
        <strong>{{ accountSelected.accountNumber }}</strong
        >?
      </p>
      <template #modal-footer="{ cancel }">
        <b-button size="sm" variant="light" @click="cancel()">Voltar</b-button>
        <b-button size="sm" variant="danger" @click="decidedToDelete"
          >Confirmar Eliminação</b-button
        >
      </template>
    </b-modal>
  </b-container>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import logs from "../../utils/logs";

export default {
  name: "AccountsComponent",

  data: () => ({
    form: {
      id: 0,
      accountHolder: "",
      accountDescription: "",
      accountNumber: "",
      companyId: null,
      createdBy: "",
      updatedBy: "",
    },
    accountDeletionId: 0,
    accountSelected: {},
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "company", "accounts"]),
  },

  created() {
    this.getAllAccounts();
  },

  methods: {
    async getAllAccounts() {
      await this.$store.dispatch("getAllAccounts", this.company.id);
    },

    openAccountModal() {
      this.resetFields();
      this.$refs["open-account"].show();
    },

    updateAccount(account) {
      this.form = { ...account }; // Clone do objeto para evitar mutação direta
      this.$refs["open-account"].show();
    },

    async saveAccount() {
      // Validações básicas
      if (this.form.accountDescription.length < 3) {
        return this.showToast(
          "Erro",
          "warning",
          "Descrição da conta inválida."
        );
      }
      if (this.form.accountNumber.length < 5) {
        return this.showToast(
          "Erro",
          "warning",
          "Número de conta demasiado curto."
        );
      }

      this.$store.commit("LOADING_STATUS", true);
      const isUpdate = this.form.id > 0;
      const url = isUpdate ? `/api/account/${this.form.id}` : "/api/account";
      const method = isUpdate ? "put" : "post";

      // Preparar payload
      const payload = {
        ...this.form,
        companyId: this.company.id,
        updatedBy: this.user.name,
        createdBy: isUpdate ? this.form.createdBy : this.user.name,
      };

      try {
        const { data } = await axios[method](url, payload);
        if (data.success) {
          this.showToast("Sucesso", "success", data.message);

          const logText = `${payload.accountNumber} ${
            isUpdate ? "atualizada" : "criada"
          } por ${this.user.name}`;
          this.$store.dispatch(
            "addLog",
            logs(this.user, logText, "Gestão de Contas")
          );

          this.$refs["open-account"].hide();
          this.getAllAccounts();
        } else {
          this.showToast("Erro", "danger", data.message);
        }
      } catch (err) {
        this.showToast("Erro de Conexão", "danger", err.message);
      } finally {
        this.$store.commit("LOADING_STATUS", false);
      }
    },

    confirmDelete(account) {
      this.accountDeletionId = account.id;
      this.accountSelected = account;
      this.$refs["delete-account"].show();
    },

    async decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      try {
        const { data } = await axios.delete(
          `/api/account/${this.accountDeletionId}`
        );
        if (data.success) {
          this.showToast("Eliminado", "success", "Conta removida com sucesso.");
          this.getAllAccounts();
          this.$refs["delete-account"].hide();
        }
      } catch (err) {
        this.showToast("Erro", "danger", err.message);
      } finally {
        this.$store.commit("LOADING_STATUS", false);
      }
    },

    resetFields() {
      this.form = {
        id: 0,
        accountHolder: "",
        accountDescription: "",
        accountNumber: "",
        companyId: this.company.id,
      };
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(msg, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },
  },
};
</script>

<style scoped>
.table td {
  vertical-align: middle;
  font-size: 0.95rem;
}
.card {
  border-radius: 12px;
}
code {
  color: #d63384;
  font-weight: bold;
  background: #f8f9fa;
  padding: 2px 5px;
  border-radius: 4px;
}
</style>
